#include <iostream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    const int n = static_cast<int>(s.size());
    bool allSame = true;
    bool palindrome = true;

    for (int i = 1; i < n; ++i) {
        if (s[i] != s[0]) allSame = false;
    }

    for (int i = 0; i < n / 2; ++i) {
        if (s[i] != s[n - 1 - i]) {
            palindrome = false;
            break;
        }
    }

    if (allSame)
        cout << 0 << '\n';
    else if (palindrome)
        cout << n - 1 << '\n';
    else
        cout << n << '\n';

    return 0;
}

#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

string s;

int check(int l, int r)
{
    int length = r - l + 1;
    while (l <= r)
    {
        if (s[l] != s[r])
            return length;
        ++l;
        --r;
    }
    return 0;
}

int main()
{
    cin >> s;

    int ans = 0;
    for (int length = 1; length <= static_cast<int>(s.size()); ++length)
        for (int left = 0; left + length <= static_cast<int>(s.size()); ++left)
            ans = max(ans, check(left, left + length - 1));

    cout << ans << '\n';
    return 0;
}

